            font-weight: 500;
            color: #1a73e8;
        }
        .comment-time {
            color: #999;
        }
        .comment-likes {
            color: #ff6b35;
            font-size: 12px;
        }
        .replies {
            margin-left: 20px;
            border-left: 2px solid #e0e0e0;
            padding-left: 15px;
            margin-top: 10px;
        }
        .reply {
            background: #f8f9fa;
            padding: 10px;
            border-radius: 6px;
            margin-bottom: 8px;
